        try: r=json.loads(l)
        except: continue
        r['_dir']=d; M.append(r)
def textfiles(r):
    a=r.get('artefact'); 
    if not a: return []
    stem=os.path.splitext(a)[0]
    out=[]
    for cand in (f"{r['_dir']}/{stem}-text.txt", f"{r['_dir']}/{a}"):
        if os.path.exists(cand) and (cand.endswith('.txt') or cand.endswith('.json') or cand.endswith('.html') or cand.endswith('.xml')): out.append(cand)
    return out
rows=c.execute("select ref_id,tier,evidence_type,coalesce(jurisdiction,''),substr(pub_title,1,58),url,doi from evidence_sources order by ref_id").fetchall()
tot=0;have=0
for ref,t,ty,j,title,url,doi in rows:
    hits=[r for r in M if r.get('ref_id')==ref or (url and r.get('url')==url)]
    tf=[]
    for r in hits:
        if r.get('status')==200 or r.get('exit')==0:
            for f in textfiles(r):
                if f.endswith('-text.txt'): tf.append(f)
    tf=sorted(set(tf), key=lambda f:-os.path.getsize(f))
    size=os.path.getsize(tf[0]) if tf else 0
